CREATE TABLE `halamans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kategori` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `judul` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ringkasan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ikon` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `grup` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `konten` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `urutan` smallint unsigned NOT NULL DEFAULT '0',
  `tampil_di_beranda` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('draft','publikasi') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'publikasi',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `halamans_kategori_slug_unique` (`kategori`,`slug`),
  KEY `halamans_kategori_status_urutan_index` (`kategori`,`status`,`urutan`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
