INSERT INTO `halamans` VALUES (1,'tentang-kami','motto-dan-logo','Motto dan Logo','Identitas dan nilai-nilai fundamental Rumah Tahanan Negara Kelas IIB Pandeglang.','perisai',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-6 items-center py-4 bg-gray-50 p-6 rounded-2xl border border-gray-150\">\n        <div class=\"flex flex-col items-center text-center sm:border-r border-gray-200 pr-0 sm:pr-4\">\n            <div class=\"w-20 h-20 bg-gradient-to-br from-gray-900 to-blue-950 rounded-2xl flex items-center justify-center text-amber-400 shadow-md mb-3\">\n                <svg class=\"w-10 h-10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\">\n                    <path stroke-linecap=\"round\" stroke-linejoin=\"round\" d=\"M9 12.75L11.25 15 15 9.75m-3-7.036A11.959 11.959 0 013.598 6 11.99 11.99 0 003 9.749c0 5.592 3.824 10.29 9 11.623 5.176-1.332 9-6.03 9-11.622 0-1.31-.21-2.571-.598-3.751h-.152c-3.196 0-6.1-1.248-8.25-3.285z\"/>\n                </svg>\n            </div>\n            <span class=\"text-xs font-bold text-gray-900\">Lambang Pemasyarakatan</span>\n            <span class=\"text-[10px] text-gray-500 mt-0.5\">Pengayoman & Pembinaan</span>\n        </div>\n        <div class=\"sm:col-span-2 space-y-2\">\n            <h3 class=\"text-base font-bold text-gray-900\">Makna dan Filosofi Lambang</h3>\n            <p class=\"text-xs text-gray-600 leading-relaxed\">\n                Lambang Pemasyarakatan melambangkan perlindungan, pengayoman, serta tekad kuat untuk membimbing Warga Binaan Pemasyarakatan (WBP) agar menyadari kesalahan, memperbaiki diri, dan tidak mengulangi tindak pidana sehingga dapat diterima kembali oleh lingkungan masyarakat.\n            </p>\n        </div>\n    </div>\n\n    <div>\n        <h3 class=\"text-base font-bold text-gray-900 mb-3\">Tata Nilai Budaya Kerja: PASTI</h3>\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3\">\n            <div class=\"p-3.5 bg-white border border-gray-200 rounded-xl shadow-xs\">\n                <span class=\"font-extrabold text-red-600 text-sm\">P - Profesional</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Aparat rutan bekerja tuntas dan akurat atas dasar kompetensi terbaik.</p>\n            </div>\n            <div class=\"p-3.5 bg-white border border-gray-200 rounded-xl shadow-xs\">\n                <span class=\"font-extrabold text-red-600 text-sm\">A - Akuntabel</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Setiap pelaksanaan tugas dan anggaran dapat dipertanggungjawabkan kepada publik.</p>\n            </div>\n            <div class=\"p-3.5 bg-white border border-gray-200 rounded-xl shadow-xs\">\n                <span class=\"font-extrabold text-red-600 text-sm\">S - Sinergi</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Membangun komitmen kerja sama produktif dengan aparat penegak hukum (APH) & stakeholder.</p>\n            </div>\n            <div class=\"p-3.5 bg-white border border-gray-200 rounded-xl shadow-xs\">\n                <span class=\"font-extrabold text-red-600 text-sm\">T - Transparan</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Menjamin keterbukaan informasi publik dan kepastian seluruh layanan tanpa pungli.</p>\n            </div>\n            <div class=\"p-3.5 bg-white border border-gray-200 rounded-xl shadow-xs sm:col-span-2\">\n                <span class=\"font-extrabold text-red-600 text-sm\">I - Inovatif</span>\n                <p class=\"text-xs text-gray-600 mt-1\">Selalu berdaya cipta memberikan terobosan kemudahan layanan bagi masyarakat dan keluarga warga binaan.</p>\n            </div>\n        </div>\n    </div>\n\n    <div class=\"pt-2 border-t border-gray-150\">\n        <h3 class=\"text-base font-bold text-gray-900 mb-2\">Core Values ASN BerAKHLAK</h3>\n        <p class=\"text-xs text-gray-600 leading-relaxed\">\n            Seluruh pegawai Rutan Kelas IIB Pandeglang memegang teguh core values ASN: <strong>Berorientasi Pelayanan, Akuntabel, Kompeten, Harmonis, Loyal, Adaptif, dan Kolaboratif</strong> dengan semboyan bangga melayani bangsa.\n        </p>\n    </div>\n</div>\n',1,0,'publikasi','2026-10-15 02:41:43','2026-10-15 02:41:43'),(2,'tentang-kami','sejarah','Sejarah','Perjalanan sejarah berdirinya Rumah Tahanan Negara Kelas IIB Pandeglang.','buku',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"prose prose-sm max-w-none text-gray-700 space-y-4 text-justify\">\n        <p>\n            Rumah Tahanan Negara (Rutan) Kelas IIB Pandeglang didirikan sebagai instansi penegak hukum di wilayah Kabupaten Pandeglang guna menjalankan fungsi penahanan dan pemeliharaan tertib keamanan tahanan yang masih menjalani proses peradilan, serta pembinaan bagi narapidana berkategori tertentu.\n        </p>\n\n        <p>\n            Seiring perkembangan sistem ketatanegaraan dan reformasi hukum nasional, sistem pemasyarakatan bertransformasi dari sistem kepenjaraan kolonial masa lampau menjadi <strong>Sistem Pemasyarakatan Indonesia</strong> yang berasaskan Pancasila, di mana narapidana dan tahanan dipandang sebagai manusia seutuhnya yang memiliki harkat dan martabat yang harus dihormati.\n        </p>\n\n        <div class=\"bg-gray-50 border-l-4 border-red-600 p-4 rounded-r-xl\">\n            <h4 class=\"font-bold text-gray-900 text-xs uppercase tracking-wider mb-1\">Transformasi Kelembagaan</h4>\n            <p class=\"text-xs text-gray-600\">\n                Kini, Rutan Kelas IIB Pandeglang berdiri kokoh di bawah naungan <strong>Kementerian Imigrasi dan Pemasyarakatan Republik Indonesia</strong> dan berkoordinasi langsung dengan Kantor Wilayah Direktorat Jenderal Pemasyarakatan Banten, terus berbenah melalui digitalisasi layanan, pembangunan Zona Integritas (ZI), dan pemenuhan hak-hak asasi warga binaan.\n            </p>\n        </div>\n\n        <p>\n            Gedung Rutan Pandeglang yang beralamat di Jalan Raya Pandeglang - Serang telah mengalami berbagai pemugaran sarana prasarana, penambahan ruang poliklinik kesehatan, blok hunian ramah HAM, bengkel kerja kemandirian, hingga ruang layanan kunjungan terpadu yang nyaman bagi masyarakat.\n        </p>\n    </div>\n</div>\n',2,0,'publikasi','2026-10-15 02:41:43','2026-10-31 16:16:01'),(3,'tentang-kami','unit-pelaksana-teknis','Unit Pelaksana Teknis','Kedudukan Rutan Pandeglang sebagai Unit Pelaksana Teknis Pemasyarakatan.','gedung',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4\">\n        <p>\n            Rumah Tahanan Negara Kelas IIB Pandeglang merupakan <strong>Unit Pelaksana Teknis (UPT)</strong> di bidang pemasyarakatan yang berada di bawah dan bertanggung jawab langsung kepada Kepala Kantor Wilayah Direktorat Jenderal Pemasyarakatan Banten.\n        </p>\n\n        <div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-3\">\n            <h4 class=\"font-bold text-gray-900 text-sm\">Data Satuan Kerja</h4>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs\">\n                <div>\n                    <span class=\"text-gray-500\">Nama Satuan Kerja:</span>\n                    <p class=\"font-semibold text-gray-900\">Rutan Kelas IIB Pandeglang</p>\n                </div>\n                <div>\n                    <span class=\"text-gray-500\">Klasifikasi Satker:</span>\n                    <p class=\"font-semibold text-gray-900\">Kelas IIB</p>\n                </div>\n                <div>\n                    <span class=\"text-gray-500\">Kantor Wilayah Induk:</span>\n                    <p class=\"font-semibold text-gray-900\">Kanwil Ditjen Pemasyarakatan Banten</p>\n                </div>\n                <div>\n                    <span class=\"text-gray-500\">Wilayah Hukum (Jurisdiksi):</span>\n                    <p class=\"font-semibold text-gray-900\">Kabupaten Pandeglang, Provinsi Banten</p>\n                </div>\n            </div>\n        </div>\n\n        <h4 class=\"font-bold text-gray-900 text-sm mt-4\">Mitra Aparat Penegak Hukum (APH) Terkait</h4>\n        <p class=\"text-xs text-gray-600\">\n            Sebagai UPT Pemasyarakatan yang mengemban penahanan, Rutan Pandeglang senantiasa bersinergi secara aktif dengan:\n        </p>\n        <ul class=\"list-disc list-inside text-xs text-gray-600 space-y-1 pl-2\">\n            <li>Kepolisian Resor (Polres) Pandeglang & Polsek jajaran</li>\n            <li>Kejaksaan Negeri (Kejari) Pandeglang</li>\n            <li>Pengadilan Negeri (PN) Pandeglang</li>\n            <li>Badan Narkotika Nasional Provinsi/Kabupaten (BNNP/BNNK)</li>\n            <li>Dinas Kesehatan dan Stakeholder Terkait di Kab. Pandeglang</li>\n        </ul>\n    </div>\n</div>\n',3,0,'publikasi','2026-10-15 02:41:43','2026-10-31 16:16:01'),(4,'tentang-kami','profil-organisasi','Profil Organisasi','Visi, misi, tugas pokok, dan fungsi institusi.','info',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <!-- Visi & Misi Card -->\n    <div class=\"space-y-4\">\n        <div class=\"bg-red-50/50 border border-red-200 rounded-xl p-5\">\n            <h3 class=\"text-sm font-extrabold text-red-700 uppercase tracking-wider mb-2\">Visi Organisasi</h3>\n            <p class=\"text-xs text-gray-800 italic leading-relaxed font-medium\">\n                \"Terwujudnya Penegakan Hukum Pemasyarakatan yang Berkeadilan, Menjunjung Tinggi HAM, dan Terpercaya dalam Membangun Kemandirian Warga Binaan Pemasyarakatan.\"\n            </p>\n        </div>\n\n        <div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5\">\n            <h3 class=\"text-sm font-extrabold text-gray-900 uppercase tracking-wider mb-2\">Misi Organisasi</h3>\n            <ol class=\"list-decimal list-inside text-xs text-gray-700 space-y-1.5 leading-relaxed\">\n                <li>Melaksanakan perawatan dan pelayanan tahanan secara profesional dan humanis.</li>\n                <li>Melaksanakan pembinaan kepribadian dan kemandirian narapidana secara berkesinambungan.</li>\n                <li>Menjaga keamanan dan ketertiban rutan melalui deteksi dini dan sinergitas APH.</li>\n                <li>Mewujudkan tata kelola pemerintahan yang bersih, transparan, dan bebas dari korupsi (WBK).</li>\n                <li>Memberikan pelayanan publik berbasis teknologi informasi yang cepat dan bebas pungli.</li>\n            </ol>\n        </div>\n    </div>\n\n    <!-- Tugas Pokok & Fungsi -->\n    <div class=\"pt-2 border-t border-gray-150\">\n        <h3 class=\"text-base font-bold text-gray-900 mb-2\">Tugas Pokok & Fungsi</h3>\n        <p class=\"text-xs text-gray-600 mb-3\">\n            Berdasarkan regulasi yang berlaku, Rutan Kelas IIB Pandeglang mempunyai tugas pokok melaksanakan perawatan terhadap tersangka atau terdakwa sesuai dengan peraturan perundang-undangan.\n        </p>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs\">\n            <div class=\"p-3 border border-gray-200 rounded-lg bg-white\">\n                <span class=\"font-bold text-gray-900 block mb-1\">1. Pelayanan Tahanan</span>\n                <p class=\"text-gray-600\">Penerimaan, pendaftaran, administrasi penahanan, perawatan jasmani, dan bantuan hukum.</p>\n            </div>\n            <div class=\"p-3 border border-gray-200 rounded-lg bg-white\">\n                <span class=\"font-bold text-gray-900 block mb-1\">2. Pemeliharaan Keamanan</span>\n                <p class=\"text-gray-600\">Penjagaan, pengawalan, penggeledahan rutin, dan penegakan tata tertib rutan.</p>\n            </div>\n            <div class=\"p-3 border border-gray-200 rounded-lg bg-white\">\n                <span class=\"font-bold text-gray-900 block mb-1\">3. Pengelolaan Rutan</span>\n                <p class=\"text-gray-600\">Urusan kepegawaian, keuangan, surat-menyurat, perlengkapan, dan rumah tangga rutan.</p>\n            </div>\n            <div class=\"p-3 border border-gray-200 rounded-lg bg-white\">\n                <span class=\"font-bold text-gray-900 block mb-1\">4. Pembinaan Kepribadian</span>\n                <p class=\"text-gray-600\">Kegiatan keagamaan, penyuluhan mental, dan pembekalan keterampilan dasar.</p>\n            </div>\n        </div>\n    </div>\n</div>\n',4,0,'publikasi','2026-10-15 02:41:43','2026-10-15 02:41:43'),(5,'tentang-kami','profil-pejabat','Profil Pejabat','Pimpinan dan jajaran pejabat struktural Rumah Tahanan Negara Kelas IIB Pandeglang.','pengguna',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <!-- Pimpinan Tertinggi / Karutan -->\n    <div class=\"bg-gray-50 border border-gray-200 rounded-2xl p-6 flex flex-col sm:flex-row items-center gap-6\">\n        <div class=\"w-24 h-24 rounded-2xl bg-gray-900 border-2 border-red-600 flex items-center justify-center text-white shrink-0 shadow-lg\">\n            <svg class=\"w-12 h-12 text-gray-400\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z\"/>\n            </svg>\n        </div>\n        <div class=\"text-center sm:text-left space-y-1\">\n            <span class=\"inline-block px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase bg-red-100 text-red-700 mb-1\">\n                Pimpinan Satuan Kerja\n            </span>\n            <h3 class=\"text-lg font-bold text-gray-900\">Kepala Rumah Tahanan Negara (Karutan)</h3>\n            <p class=\"text-xs text-gray-600\">Rumah Tahanan Negara Kelas IIB Pandeglang</p>\n            <p class=\"text-xs text-gray-500 pt-1 leading-relaxed\">\n                Bertanggung jawab memimpin, mengoordinasikan, dan mengawasi seluruh pelaksanaan tugas perawatan tahanan, pemeliharaan keamanan ketertiban, serta pengelolaan tata usaha rutan.\n            </p>\n        </div>\n    </div>\n\n    <!-- Pejabat Struktural Eselon V -->\n    <div class=\"space-y-3 pt-2\">\n        <h3 class=\"text-sm font-bold uppercase tracking-wider text-gray-900\">Pejabat Struktural Terkait</h3>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n            <!-- Ka KPR -->\n            <div class=\"bg-white border border-gray-200 rounded-xl p-4 text-center space-y-2 hover:shadow-md transition\">\n                <div class=\"w-14 h-14 mx-auto rounded-full bg-gray-100 border border-gray-200 flex items-center justify-center text-gray-500\">\n                    <svg class=\"w-7 h-7\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                        <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/>\n                    </svg>\n                </div>\n                <h4 class=\"font-bold text-gray-900 text-xs\">Kepala Kesatuan Pengamanan Rutan (Ka KPR)</h4>\n                <p class=\"text-[11px] text-gray-500 leading-snug\">Menjaga stabilitas ketertiban, penjagaan blok, dan pencegahan gangguan kamtib.</p>\n            </div>\n\n            <!-- Kasubsie Pelayanan Tahanan -->\n            <div class=\"bg-white border border-gray-200 rounded-xl p-4 text-center space-y-2 hover:shadow-md transition\">\n                <div class=\"w-14 h-14 mx-auto rounded-full bg-gray-100 border border-gray-200 flex items-center justify-center text-gray-500\">\n                    <svg class=\"w-7 h-7\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                        <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z\"/>\n                    </svg>\n                </div>\n                <h4 class=\"font-bold text-gray-900 text-xs\">Kasubsie Pelayanan Tahanan</h4>\n                <p class=\"text-[11px] text-gray-500 leading-snug\">Mengelola registrasi tahanan, perawatan kesehatan, dan integrasi (PB, CB, CMB).</p>\n            </div>\n\n            <!-- Kasubsie Pengelolaan -->\n            <div class=\"bg-white border border-gray-200 rounded-xl p-4 text-center space-y-2 hover:shadow-md transition\">\n                <div class=\"w-14 h-14 mx-auto rounded-full bg-gray-100 border border-gray-200 flex items-center justify-center text-gray-500\">\n                    <svg class=\"w-7 h-7\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                        <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M9 7h6m0 10v-3m-3 3h.01M9 17h.01M9 14h.01M12 14h.01M15 11h.01M12 11h.01M9 11h.01M7 21h10a2 2 0 002-2V5a2 2 0 00-2-2H7a2 2 0 00-2 2v14a2 2 0 002 2z\"/>\n                    </svg>\n                </div>\n                <h4 class=\"font-bold text-gray-900 text-xs\">Kasubsie Pengelolaan</h4>\n                <p class=\"text-[11px] text-gray-500 leading-snug\">Mengelola tata usaha kepegawaian, keuangan, perlengkapan, dan logistik bahan makanan.</p>\n            </div>\n        </div>\n    </div>\n</div>\n',5,0,'publikasi','2026-10-15 02:41:43','2026-10-15 02:41:43'),(6,'tentang-kami','struktur-organisasi','Struktur Organisasi','Bagan susunan hirarki organisasi Rumah Tahanan Negara Kelas IIB Pandeglang.','grafik',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <!-- Bagan Visual Struktur -->\n    <div class=\"p-4 sm:p-6 bg-gray-50 border border-gray-200 rounded-2xl\">\n        <div class=\"flex flex-col items-center space-y-6\">\n            \n            <!-- Pucuk Pimpinan -->\n            <div class=\"bg-gray-900 text-white px-6 py-3 rounded-xl shadow-lg border-2 border-red-600 text-center w-full max-w-64\">\n                <span class=\"text-[10px] font-bold text-red-400 uppercase tracking-widest block\">Kepala Rutan</span>\n                <span class=\"text-xs font-bold block mt-0.5\">Rutan Kelas IIB Pandeglang</span>\n            </div>\n\n            <!-- Garis Penghubung Vertikal -->\n            <div class=\"w-0.5 h-6 bg-gray-300\"></div>\n\n            <!-- Cabang Struktural (3 Seksi/Sub) -->\n            <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4 w-full\">\n                <!-- Sub 1 -->\n                <div class=\"bg-white border border-gray-200 rounded-xl p-4 text-center shadow-xs\">\n                    <span class=\"text-[10px] font-bold text-gray-500 uppercase tracking-wider block\">Kesatuan Keamanan</span>\n                    <h4 class=\"text-xs font-bold text-gray-900 mt-1\">Kesatuan Pengamanan Rutan (KPR)</h4>\n                    <p class=\"text-[11px] text-gray-500 mt-1\">Regu Pengamanan & Staf KPR</p>\n                </div>\n\n                <!-- Sub 2 -->\n                <div class=\"bg-white border border-gray-200 rounded-xl p-4 text-center shadow-xs\">\n                    <span class=\"text-[10px] font-bold text-gray-500 uppercase tracking-wider block\">Sub Seksi 1</span>\n                    <h4 class=\"text-xs font-bold text-gray-900 mt-1\">Subseksi Pelayanan Tahanan</h4>\n                    <p class=\"text-[11px] text-gray-500 mt-1\">Registrasi, Integrasi, Perawatan & Medis</p>\n                </div>\n\n                <!-- Sub 3 -->\n                <div class=\"bg-white border border-gray-200 rounded-xl p-4 text-center shadow-xs\">\n                    <span class=\"text-[10px] font-bold text-gray-500 uppercase tracking-wider block\">Sub Seksi 2</span>\n                    <h4 class=\"text-xs font-bold text-gray-900 mt-1\">Subseksi Pengelolaan</h4>\n                    <p class=\"text-[11px] text-gray-500 mt-1\">Kepegawaian, Keuangan, Rumah Tangga</p>\n                </div>\n            </div>\n\n        </div>\n    </div>\n\n    <div class=\"text-xs text-gray-500 leading-relaxed pt-2\">\n        <p>\n            * Bagan organisasi Rutan Kelas IIB Pandeglang disusun berdasarkan Peraturan Menteri yang membidangi Pemasyarakatan dan tata naskah dinas resmi instansi.\n        </p>\n    </div>\n</div>\n',6,0,'publikasi','2026-10-15 02:41:43','2026-10-15 02:41:43'),(7,'tentang-kami','strategi-organisasi','Strategi Organisasi','Arah kebijakan dan strategi pencapaian sasaran organisasi.','ceklis',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <!-- 3 Kunci Pemasyarakatan Maju + Back to Basics -->\n    <div class=\"space-y-4\">\n        <h3 class=\"text-base font-bold text-gray-900\">3 Kunci Pemasyarakatan Maju + Back to Basics</h3>\n        <p class=\"text-xs text-gray-600\">\n            Rutan Kelas IIB Pandeglang mengimplementasikan strategi instruksi Direktur Jenderal Pemasyarakatan:\n        </p>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4 text-xs\">\n            <div class=\"p-4 bg-red-50/50 border border-red-200 rounded-xl\">\n                <span class=\"font-bold text-red-700 block mb-1\">1. Deteksi Dini</span>\n                <p class=\"text-gray-600\">Mencegah potensi gangguan keamanan melalui inspeksi mendadak, pemeliharaan gembok teralis, dan penggeledahan berkala.</p>\n            </div>\n            <div class=\"p-4 bg-red-50/50 border border-red-200 rounded-xl\">\n                <span class=\"font-bold text-red-700 block mb-1\">2. Berantas Narkoba</span>\n                <p class=\"text-gray-600\">Komitmen Zero Narkoba dan Zero Handphone di dalam blok hunian dengan tes urine rutin pegawai dan warga binaan.</p>\n            </div>\n            <div class=\"p-4 bg-red-50/50 border border-red-200 rounded-xl\">\n                <span class=\"font-bold text-red-700 block mb-1\">3. Sinergitas APH</span>\n                <p class=\"text-gray-600\">Memperkuat kerja sama operasional dengan TNI, Kepolisian, Pengadilan, dan Kejaksaan dalam proses penegakan hukum.</p>\n            </div>\n        </div>\n\n        <div class=\"p-4 bg-gray-50 border border-gray-200 rounded-xl text-xs\">\n            <span class=\"font-bold text-gray-900 block mb-1\">Prinsip Back to Basics</span>\n            <p class=\"text-gray-600\">\n                Mengembalikan seluruh prosedur pelayanan, pembinaan, dan pengamanan pemasyarakatan sesuai Standar Operasional Prosedur (SOP) dan undang-undang yang berlaku.\n            </p>\n        </div>\n    </div>\n\n    <!-- Pembangunan Zona Integritas (WBK/WBBM) -->\n    <div class=\"pt-2 border-t border-gray-150 space-y-2\">\n        <h3 class=\"text-base font-bold text-gray-900\">Pembangunan Zona Integritas (ZI)</h3>\n        <p class=\"text-xs text-gray-600\">\n            Fokus reformasi birokrasi pada 6 area perubahan: Manajemen Perubahan, Penataan Tatalaksana, Penataan Sistem Manajemen SDM, Penguatan Akuntabilitas Kinerja, Penguatan Pengawasan, dan Peningkatan Kualitas Pelayanan Publik menuju predikat <strong>Wilayah Bebas dari Korupsi (WBK)</strong>.\n        </p>\n    </div>\n</div>\n',7,0,'publikasi','2026-10-15 02:41:43','2026-10-15 02:41:43'),(8,'tentang-kami','kontak-kami','Kontak Kami','Saluran komunikasi, alamat, dan jam operasional pelayanan masyarakat.','telepon',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <!-- Info Kotak Kontak -->\n    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs\">\n        <div class=\"p-4 bg-gray-50 border border-gray-200 rounded-xl space-y-1\">\n            <span class=\"font-bold text-gray-900 block text-sm mb-2\">Alamat Kantor</span>\n            <p class=\"text-gray-600\">Jalan Raya Pandeglang - Serang</p>\n            <p class=\"text-gray-600\">Kabupaten Pandeglang, Provinsi Banten</p>\n            <p class=\"text-gray-600\">Kode Pos: 42213</p>\n        </div>\n\n        <div class=\"p-4 bg-gray-50 border border-gray-200 rounded-xl space-y-1\">\n            <span class=\"font-bold text-gray-900 block text-sm mb-2\">Saluran Digital</span>\n            <p class=\"text-gray-600\"><strong>Email:</strong> info@rutanpandeglang.go.id</p>\n            <p class=\"text-gray-600\"><strong>Telepon:</strong> (0253) 201234</p>\n            <p class=\"text-gray-600\"><strong>Layanan WhatsApp Humas:</strong> 0812-XXXX-XXXX</p>\n        </div>\n    </div>\n\n    <!-- Jam Layanan Kunjungan -->\n    <div class=\"p-5 bg-white border border-gray-200 rounded-xl space-y-2\">\n        <h3 class=\"text-sm font-bold text-gray-900\">Jadwal Pelayanan Kunjungan & Penitipan Barang</h3>\n        <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-xs text-left text-gray-600 mt-2\">\n                <thead class=\"bg-gray-100 text-gray-800 uppercase text-[10px] tracking-wider\">\n                    <tr>\n                        <th class=\"py-2 px-3\">Hari</th>\n                        <th class=\"py-2 px-3\">Sesi 1</th>\n                        <th class=\"py-2 px-3\">Sesi 2</th>\n                        <th class=\"py-2 px-3\">Keterangan</th>\n                    </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200\">\n                    <tr>\n                        <td class=\"py-2.5 px-3 font-semibold text-gray-900\">Senin</td>\n                        <td class=\"py-2.5 px-3\">08.30 - 12.00 WIB</td>\n                        <td class=\"py-2.5 px-3\">13.30 - 14.00 WIB</td>\n                        <td class=\"py-2.5 px-3 text-emerald-600 font-medium\">Kunjungan Tatap Muka & Titipan Barang</td>\n                    </tr>\n                    <tr>\n                        <td class=\"py-2.5 px-3 font-semibold text-gray-900\">Rabu</td>\n                        <td class=\"py-2.5 px-3\">08.30 - 12.00 WIB</td>\n                        <td class=\"py-2.5 px-3\">13.30 - 14.00 WIB</td>\n                        <td class=\"py-2.5 px-3 text-emerald-600 font-medium\">Kunjungan Tatap Muka & Titipan Barang</td>\n                    </tr>\n                    <tr>\n                        <td class=\"py-2.5 px-3 font-semibold text-gray-900\">Sabtu</td>\n                        <td class=\"py-2.5 px-3\">08.30 - 12.00 WIB</td>\n                        <td class=\"py-2.5 px-3\">—</td>\n                        <td class=\"py-2.5 px-3 text-emerald-600 font-medium\">Kunjungan Tatap Muka & Titipan Barang</td>\n                    </tr>\n                    <tr>\n                        <td class=\"py-2.5 px-3 font-semibold text-gray-900\">Selasa, Kamis, Jumat, Minggu & Libur</td>\n                        <td colspan=\"3\" class=\"py-2.5 px-3 text-red-600 font-semibold\">Tidak ada layanan kunjungan</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n</div>\n',8,0,'publikasi','2026-10-15 02:41:43','2026-10-15 03:31:14'),(9,'layanan','jadwal-besuk','Jadwal Besuk','Informasi jam kunjungan tatap muka Warga Binaan beserta syarat pengunjung.','kalender','Kunjungan & WBP','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\r\n<div class=\"space-y-4 text-xs\">\r\n<p class=\"text-sm leading-relaxed\">Layanan kunjungan tatap muka diselenggarakan setiap hari <strong>Senin, Rabu, dan Sabtu</strong> untuk menjaga hubungan kekeluargaan antara Warga Binaan dengan keluarga dan kerabat. Penitipan barang dan makanan dilayani pada jadwal yang sama. Seluruh layanan kunjungan <strong>tidak dipungut biaya apa pun (GRATIS)</strong>.</p>\r\n<div class=\"overflow-x-auto border border-gray-200 rounded-xl\">\r\n<table class=\"w-full text-left\">\r\n<thead class=\"bg-gray-100 text-gray-800 uppercase text-[10px] tracking-wider\">\r\n<tr>\r\n<th class=\"py-3 px-4\">Hari</th>\r\n<th class=\"py-3 px-4\">Sesi 1</th>\r\n<th class=\"py-3 px-4\">Sesi 2</th>\r\n</tr>\r\n</thead>\r\n<tbody class=\"divide-y divide-gray-200\">\r\n<tr>\r\n<td class=\"py-3 px-4 font-semibold text-gray-900\">Senin</td>\r\n<td class=\"py-3 px-4 text-gray-600\">08.30 &ndash; 12.00 WIB</td>\r\n<td class=\"py-3 px-4 text-gray-600\">13.30 &ndash; 14.00 WIB</td>\r\n</tr>\r\n<tr>\r\n<td class=\"py-3 px-4 font-semibold text-gray-900\">Rabu</td>\r\n<td class=\"py-3 px-4 text-gray-600\">08.30 &ndash; 12.00 WIB</td>\r\n<td class=\"py-3 px-4 text-gray-600\">13.30 &ndash; 14.00 WIB</td>\r\n</tr>\r\n<tr>\r\n<td class=\"py-3 px-4 font-semibold text-gray-900\">Sabtu</td>\r\n<td class=\"py-3 px-4 text-gray-600\">08.30 &ndash; 12.00 WIB</td>\r\n<td class=\"py-3 px-4 text-gray-400\">Tidak ada</td>\r\n</tr>\r\n<tr>\r\n<td class=\"py-3 px-4 font-semibold text-gray-900\">Selasa, Kamis, Jumat, Minggu &amp; Hari Libur</td>\r\n<td class=\"py-3 px-4 text-red-600 font-semibold\" colspan=\"2\">Tidak ada layanan kunjungan</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-2\">\r\n<h3 class=\"font-bold text-gray-900 text-sm mb-2\">Syarat Pengunjung:</h3>\r\n<ul class=\"list-disc list-inside text-gray-600 space-y-1.5 leading-relaxed\">\r\n<li>Membawa identitas diri yang sah dan masih berlaku (KTP / SIM / Kartu Keluarga).</li>\r\n<li>Memiliki hubungan keluarga atau kerabat dengan Warga Binaan yang dikunjungi.</li>\r\n<li>Mendaftar di loket layanan kunjungan dan bersedia diperiksa petugas.</li>\r\n<li>Berpakaian sopan dan rapi; dilarang membawa telepon genggam ke ruang kunjungan.</li>\r\n</ul>\r\n</div>\r\n<div class=\"p-4 bg-amber-50 border border-amber-200 rounded-xl space-y-1 text-amber-900\"><span class=\"font-bold\">Perhatian:</span>\r\n<p class=\"leading-relaxed\">Jadwal dapat berubah sewaktu-waktu menyesuaikan kebijakan pimpinan dan kondisi keamanan. Pantau pengumuman terbaru di menu Berita.</p>\r\n</div>\r\n</div>\r\n</div>',1,1,'publikasi','2026-10-15 02:41:43','2026-10-15 04:28:24'),(10,'layanan','titipan-barang','Titipan Barang','SOP dan syarat penitipan barang & makanan untuk Warga Binaan.','paket','Kunjungan & WBP','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4 text-xs\">\n        <p class=\"text-sm leading-relaxed\">\n            Keluarga dapat menitipkan barang kebutuhan sehari-hari dan makanan untuk Warga Binaan melalui loket layanan penitipan, <strong>hanya pada hari dan sesi kunjungan</strong>: Senin &amp; Rabu (08.30–12.00 dan 13.30–14.00 WIB) serta Sabtu (08.30–12.00 WIB). Setiap titipan wajib melalui pemeriksaan petugas demi menjaga keamanan dan ketertiban rutan.\n        </p>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"p-5 bg-emerald-50/60 border border-emerald-200 rounded-xl space-y-2\">\n                <h3 class=\"font-bold text-emerald-900 text-sm\">Barang yang Diperbolehkan</h3>\n                <ul class=\"list-disc list-inside text-gray-600 space-y-1 leading-relaxed\">\n                    <li>Pakaian layak pakai (tidak bermotif loreng).</li>\n                    <li>Perlengkapan mandi dalam kemasan bening.</li>\n                    <li>Makanan matang dalam wadah plastik transparan.</li>\n                    <li>Buku bacaan dan perlengkapan ibadah.</li>\n                </ul>\n            </div>\n            <div class=\"p-5 bg-red-50/60 border border-red-200 rounded-xl space-y-2\">\n                <h3 class=\"font-bold text-red-900 text-sm\">Barang yang Dilarang</h3>\n                <ul class=\"list-disc list-inside text-gray-600 space-y-1 leading-relaxed\">\n                    <li>Telepon genggam, kartu SIM, dan perangkat elektronik.</li>\n                    <li>Narkotika, obat-obatan tanpa resep, dan minuman beralkohol.</li>\n                    <li>Senjata tajam, benda logam, dan korek api.</li>\n                    <li>Uang tunai dalam bentuk apa pun.</li>\n                </ul>\n            </div>\n        </div>\n\n        <div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm mb-2\">Alur Penitipan:</h3>\n            <ol class=\"list-decimal list-inside text-gray-600 space-y-1.5 leading-relaxed\">\n                <li>Mendaftar di loket penitipan dengan menunjukkan identitas diri.</li>\n                <li>Mengisi formulir penitipan sesuai nama dan blok Warga Binaan.</li>\n                <li>Barang diperiksa petugas di hadapan penitip.</li>\n                <li>Barang yang lolos pemeriksaan diserahkan kepada Warga Binaan oleh petugas.</li>\n            </ol>\n        </div>\n\n        <div class=\"p-4 bg-gray-900 text-gray-200 rounded-xl\">\n            Layanan penitipan barang <strong class=\"text-amber-400\">tidak dipungut biaya</strong>. Laporkan setiap permintaan imbalan melalui menu Pengaduan.\n        </div>\n    </div>\n</div>\n',2,1,'publikasi','2026-10-15 02:41:43','2026-10-15 03:31:14'),(11,'layanan','program-integrasi','Program Integrasi','Layanan pengurusan PB, CB, dan CMB resmi tanpa biaya.','pintu-keluar','Kunjungan & WBP','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4 text-xs\">\n        <p class=\"text-sm leading-relaxed\">\n            Program integrasi merupakan hak Warga Binaan yang telah memenuhi syarat substantif dan administratif untuk menjalani sisa masa pidana di tengah masyarakat di bawah bimbingan Balai Pemasyarakatan (Bapas).\n        </p>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n            <div class=\"p-4 bg-white border border-gray-200 rounded-xl space-y-1\">\n                <span class=\"inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase bg-gray-900 text-white\">PB</span>\n                <h3 class=\"font-bold text-gray-900 text-sm\">Pembebasan Bersyarat</h3>\n                <p class=\"text-gray-600\">Telah menjalani minimal 2/3 masa pidana dengan ketentuan 2/3 tersebut paling sedikit 9 bulan.</p>\n            </div>\n            <div class=\"p-4 bg-white border border-gray-200 rounded-xl space-y-1\">\n                <span class=\"inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase bg-gray-900 text-white\">CB</span>\n                <h3 class=\"font-bold text-gray-900 text-sm\">Cuti Bersyarat</h3>\n                <p class=\"text-gray-600\">Bagi Warga Binaan dengan pidana paling lama 1 tahun 3 bulan yang telah menjalani 2/3 masa pidana.</p>\n            </div>\n            <div class=\"p-4 bg-white border border-gray-200 rounded-xl space-y-1\">\n                <span class=\"inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase bg-gray-900 text-white\">CMB</span>\n                <h3 class=\"font-bold text-gray-900 text-sm\">Cuti Menjelang Bebas</h3>\n                <p class=\"text-gray-600\">Diberikan menjelang berakhirnya masa pidana bagi Warga Binaan yang memenuhi syarat.</p>\n            </div>\n        </div>\n\n        <div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm mb-2\">Dokumen yang Disiapkan Keluarga / Penjamin:</h3>\n            <ul class=\"list-disc list-inside text-gray-600 space-y-1.5 leading-relaxed\">\n                <li>Surat jaminan kesanggupan dari pihak keluarga / penjamin.</li>\n                <li>Fotokopi KTP penjamin dan Kartu Keluarga.</li>\n                <li>Surat keterangan dari kelurahan/desa tempat tinggal penjamin.</li>\n                <li>Kelengkapan lain sesuai arahan petugas registrasi.</li>\n            </ul>\n        </div>\n\n        <div class=\"p-4 bg-emerald-50 border border-emerald-200 rounded-xl space-y-1 text-emerald-900\">\n            <span class=\"font-bold\">Gratis & Transparan:</span>\n            <p class=\"leading-relaxed\">\n                Seluruh proses pengusulan program integrasi <strong>tidak dipungut biaya</strong>. Informasi status usulan dapat ditanyakan langsung ke loket layanan registrasi.\n            </p>\n        </div>\n    </div>\n</div>\n',3,1,'publikasi','2026-10-15 02:41:43','2026-10-15 02:41:43'),(12,'layanan','permohonan-data-dan-informasi','Permohonan Data dan Informasi','Layanan PPID untuk permohonan data dan informasi publik.','dokumen','Informasi & Pengaduan','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4\">\n        <p>\n            Berdasarkan Undang-Undang Nomor 14 Tahun 2008 tentang Keterbukaan Informasi Publik, setiap warga negara berhak memperoleh informasi publik yang dikelola oleh instansi pemerintah secara cepat, tepat waktu, dan berbiaya ringan.\n        </p>\n\n        <!-- Tahapan Alur Permohonan -->\n        <div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-3\">\n            <h3 class=\"font-bold text-gray-900 text-sm\">Alur & Prosedur Permohonan Informasi:</h3>\n            <ol class=\"list-decimal list-inside text-xs text-gray-600 space-y-2 leading-relaxed\">\n                <li><strong>Pengajuan Permohonan:</strong> Pemohon mengisi formulir permohonan informasi publik dengan melampirkan fotokopi/scan KTP atau identitas diri yang sah.</li>\n                <li><strong>Verifikasi Dokumen:</strong> Petugas PPID Rutan Pandeglang memeriksa kelengkapan administrasi dan keabsahan tujuan permohonan.</li>\n                <li><strong>Penyusunan Tanggapan:</strong> PPID memproses dan mengoordinasikan ketersediaan dokumen maksimal dalam 10 (sepuluh) hari kerja.</li>\n                <li><strong>Pemberian Informasi:</strong> Pemohon menerima dokumen informasi publik yang diminta secara langsung atau melalui surat elektronik (email).</li>\n            </ol>\n        </div>\n\n        <div class=\"p-4 bg-red-50/60 border border-red-200 rounded-xl text-xs space-y-1\">\n            <span class=\"font-bold text-red-800\">Catatan Penting:</span>\n            <p class=\"text-gray-700\">\n                Layanan permohonan informasi publik ini <strong>TIDAK DIPUNGUT BIAYA (GRATIS)</strong>. Informasi yang dikecualikan (rahasia negara/keamanan blok hunian tahanan) tidak dapat dipublikasikan sesuai peraturan perundang-undangan.\n            </p>\n        </div>\n    </div>\n</div>\n',4,0,'publikasi','2026-10-15 02:41:43','2026-10-15 04:16:05'),(13,'layanan','media-massa','Media Massa','Rilis pers, konfirmasi pemberitaan, dan wawancara jurnalis resmi.','megafon','Informasi & Pengaduan','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4\">\n        <p>\n            Subbagian Humas Rutan Kelas IIB Pandeglang membuka ruang kemitraan yang luas bagi insan pers dan jurnalis media cetak, elektronik, maupun daring (online) yang terverifikasi Dewan Pers untuk menyebarluaskan berita positif dan transparansi kegiatan pemasyarakatan.\n        </p>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs\">\n            <div class=\"p-4 bg-gray-50 border border-gray-200 rounded-xl space-y-1.5\">\n                <h4 class=\"font-bold text-gray-900\">Siaran Pers Resmi</h4>\n                <p class=\"text-gray-600 leading-relaxed\">\n                    Setiap kegiatan giat, razia, pembinaan, maupun seremonial resmi rutan diterbitkan melalui siaran pers resmi yang dapat diakses publik melalui rubrik Berita portal ini.\n                </p>\n            </div>\n\n            <div class=\"p-4 bg-gray-50 border border-gray-200 rounded-xl space-y-1.5\">\n                <h4 class=\"font-bold text-gray-900\">Permohonan Wawancara</h4>\n                <p class=\"text-gray-600 leading-relaxed\">\n                    Jurnalis yang hendak melakukan konfirmasi berita atau wawancara dengan Kepala Rutan/Pejabat Struktural dapat mengirimkan surat permohonan melalui email <strong>humas@rutanpandeglang.go.id</strong>.\n                </p>\n            </div>\n        </div>\n\n        <div class=\"bg-white border border-gray-200 rounded-xl p-4 text-xs space-y-1\">\n            <span class=\"font-bold text-gray-900\">Kontak Media Center / Humas:</span>\n            <p class=\"text-gray-600\">WhatsApp Media Relations: <strong>0812-XXXX-XXXX</strong> (Hanya untuk keperluan kedinasan pers)</p>\n        </div>\n    </div>\n</div>\n',5,0,'publikasi','2026-10-15 02:41:43','2026-10-15 04:16:05'),(14,'layanan','simonev-bama','SIMONEV Bama Kemenimipas','Monitoring dan evaluasi penyelenggaraan makanan bagi Warga Binaan.','ceklis','Informasi & Pengaduan','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4 text-xs\">\n        <p class=\"text-sm leading-relaxed\">\n            Rutan Kelas IIB Pandeglang mengimplementasikan pengawasan ketat terhadap penyelenggaraan makanan bagi tahanan dan warga binaan melalui integrasi pelaporan <strong>SIMONEV Bama</strong> dari Direktorat Jenderal Pemasyarakatan.\n        </p>\n\n        <div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-3\">\n            <h3 class=\"font-bold text-gray-900 text-sm\">Standar Penyelenggaraan Makanan di Rutan Pandeglang:</h3>\n            <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs\">\n                <div class=\"p-3 bg-white border border-gray-200 rounded-lg\">\n                    <span class=\"font-bold text-gray-900 block mb-1\">Kecukupan Angka Gizi & Kalori</span>\n                    <p class=\"text-gray-600\">Pemberian menu harian yang seimbang dan bervariasi sesuai standar Permenkumham/Kemenimipas.</p>\n                </div>\n                <div class=\"p-3 bg-white border border-gray-200 rounded-lg\">\n                    <span class=\"font-bold text-gray-900 block mb-1\">Sertifikat Laik Higiene Sanitasi</span>\n                    <p class=\"text-gray-600\">Dapur rutan telah melalui uji laboratorium kesehatan berkala dari Dinas Kesehatan setempat.</p>\n                </div>\n                <div class=\"p-3 bg-white border border-gray-200 rounded-lg\">\n                    <span class=\"font-bold text-gray-900 block mb-1\">Distribusi Makanan Tepat Waktu</span>\n                    <p class=\"text-gray-600\">Jadwal pembagian makan 3 kali sehari (Pagi, Siang, dan Sore) secara tertib dan terjaga suhunya.</p>\n                </div>\n                <div class=\"p-3 bg-white border border-gray-200 rounded-lg\">\n                    <span class=\"font-bold text-gray-900 block mb-1\">Peralatan Dapur Higienis</span>\n                    <p class=\"text-gray-600\">Seluruh perkakas masak, tempat makan ompreng, dan air minum diproses melalui sterilisasi bersih.</p>\n                </div>\n            </div>\n        </div>\n\n        <p class=\"text-gray-600 leading-relaxed\">\n            Data pemenuhan bahan makanan diinput secara berkala ke aplikasi pusat sebagai bentuk akuntabilitas pertanggungjawaban anggaran negara dan pemenuhan hak asasi dasar warga binaan.\n        </p>\n    </div>\n</div>\n',6,0,'publikasi','2026-10-15 02:41:43','2026-10-15 04:16:05'),(15,'layanan','perizinan-penelitian','Perizinan Penelitian','Syarat dan mekanisme izin penelitian skripsi, tesis, dan riset akademis.','toga','Perizinan','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\r\n<div class=\"space-y-4 text-xs\">\r\n<p class=\"text-sm leading-relaxed\">Rutan Kelas IIB Pandeglang memfasilitasi mahasiswa, akademisi, dan lembaga riset independen yang bermaksud melaksanakan penelitian ilmiah di bidang hukum, kriminologi, sosiologi, psikologi, maupun pemasyarakatan.</p>\r\n<div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-2\">\r\n<h3 class=\"font-bold text-gray-900 text-sm mb-2\">Persyaratan Dokumen Administrasi:</h3>\r\n<ul class=\"list-disc list-inside text-gray-600 space-y-1.5 leading-relaxed\">\r\n<li>Surat Rekomendasi/Izin Penelitian dari Kantor Wilayah Ditjen Pemasyarakatan Banten.</li>\r\n<li>Surat Pengantar resmi dari Rektorat / Dekanat Perguruan Tinggi yang bersangkutan.</li>\r\n<li>Proposal Penelitian lengkap (beserta instrumen angket/kuesioner/pedoman wawancara).</li>\r\n<li>Salinan Kartu Tanda Penduduk (KTP) dan Kartu Tanda Mahasiswa (KTM).</li>\r\n<li>Surat Pernyataan kesanggupan menaati tata tertib dan menjaga kerahasiaan identitas tahanan/WBP.</li>\r\n</ul>\r\n</div>\r\n<div class=\"p-4 bg-white border border-gray-200 rounded-xl space-y-1\"><span class=\"font-bold text-gray-900\">Tata Cara Pengajuan:</span>\r\n<p class=\"text-gray-600 leading-relaxed\">Berkas persyaratan diserahkan ke bagian Tata Usaha / Pengelolaan Rutan Pandeglang pada hari kerja (Senin - Jumat, pukul 08.00 - 14.00 WIB) untuk diverifikasi oleh tim pengamanan sebelum jadwal penelitian ditetapkan.</p>\r\n</div>\r\n</div>\r\n</div>',7,1,'publikasi','2026-10-15 02:41:43','2026-10-31 16:16:01'),(16,'layanan','perizinan-magang','Perizinan Magang','Ketentuan dan prosedur pengajuan magang bagi siswa SMK dan mahasiswa.','koper','Perizinan','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4 text-xs\">\n        <p class=\"text-sm leading-relaxed\">\n            Program Magang/PKL di Rutan Kelas IIB Pandeglang memberikan kesempatan bagi generasi muda untuk memahami secara langsung tata kelola administrasi pemasyarakatan, pelayanan publik, manajemen berkas penahanan, dan sistem hukum pidana.\n        </p>\n\n        <div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm mb-2\">Persyaratan Pengajuan Magang:</h3>\n            <ul class=\"list-disc list-inside text-gray-600 space-y-1.5 leading-relaxed\">\n                <li>Surat permohonan resmi dari pihak Sekolah / Perguruan Tinggi yang ditujukan kepada Kepala Rutan Kelas IIB Pandeglang.</li>\n                <li>Daftar nama peserta magang beserta program studi / jurusan.</li>\n                <li>Curriculum Vitae (CV) singkat dan pas foto 3x4 (2 lembar).</li>\n                <li>Salinan Kartu Tanda Mahasiswa (KTM) / Kartu Pelajar.</li>\n                <li>Proposal rencana kegiatan dan durasi pelaksanaan magang.</li>\n            </ul>\n        </div>\n\n        <div class=\"p-4 bg-emerald-50 border border-emerald-200 rounded-xl space-y-1 text-emerald-900\">\n            <span class=\"font-bold\">Ketentuan Pelaksanaan:</span>\n            <p class=\"leading-relaxed\">\n                Penerimaan magang disesuaikan dengan kuota ketersediaan di masing-masing subseksi (Pengelolaan, Pelayanan Tahanan, dan Kesatuan Pengamanan). Seluruh rangkaian kegiatan magang <strong>tidak dipungut biaya</strong>.\n            </p>\n        </div>\n    </div>\n</div>\n',8,0,'publikasi','2026-10-15 02:41:43','2026-10-15 04:16:05'),(17,'layanan','perizinan-peliputan','Perizinan Peliputan','SOP dokumentasi visual, video, dan liputan berita di area rutan.','kamera','Perizinan','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4 text-xs\">\n        <p class=\"text-sm leading-relaxed\">\n            Demi menjaga keamanan, ketertiban, dan hak privasi narapidana/tahanan, peliputan oleh media massa, stasiun televisi, dan jurnalis di dalam area Rumah Tahanan Negara Kelas IIB Pandeglang wajib mematuhi standar operasional prosedur (SOP) yang ketat.\n        </p>\n\n        <div class=\"bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-2\">\n            <h3 class=\"font-bold text-gray-900 text-sm mb-2\">Prosedur Pengajuan Izin Peliputan:</h3>\n            <ol class=\"list-decimal list-inside text-gray-600 space-y-2 leading-relaxed\">\n                <li>Mengirimkan surat tugas peliputan dari pimpinan redaksi resmi minimal H-2 sebelum kegiatan.</li>\n                <li>Mencantumkan topik liputan, daftar kru, serta jenis peralatan kamera/video yang dibawa.</li>\n                <li>Melakukan registrasi dan pemeriksaan identitas pers di pos penjagaan pintu utama (P2U).</li>\n                <li>Menandatangani lembar persetujuan tata tertib pengamanan dan etika jurnalistik pemasyarakatan.</li>\n            </ol>\n        </div>\n\n        <div class=\"p-4 bg-amber-50 border border-amber-200 rounded-xl space-y-1 text-amber-950\">\n            <span class=\"font-bold\">Ketentuan Khusus Perlindungan Hak WBP:</span>\n            <p class=\"leading-relaxed\">\n                Dilarang mengambil foto/video wajah warga binaan secara jelas tanpa izin tertulis (informed consent) dari yang bersangkutan demi menjunjung tinggi asas praduga tak bersalah dan perlindungan masa depan anak/keluarga binaan.\n            </p>\n        </div>\n    </div>\n</div>\n',9,0,'publikasi','2026-10-15 02:41:43','2026-10-15 04:16:05'),(18,'layanan','pengaduan','Pengaduan','Saluran aspirasi, laporan pungli, gratifikasi, dan ketidakpuasan layanan.','chat','Informasi & Pengaduan','<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\r\n<div class=\"space-y-4 text-xs\">\r\n<p class=\"text-sm leading-relaxed\">Rutan Kelas IIB Pandeglang berkomitmen memberikan pelayanan yang bersih, transparan, dan bebas pungutan liar. Masyarakat yang menemukan pelanggaran kode etik, indikasi pungli, diskriminasi layanan, atau peredaran barang terlarang dipersilakan melapor melalui kanal resmi kami.</p>\r\n<!-- Kanal Pengaduan Cards -->\r\n<div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\"><!-- SP4N LAPOR -->\r\n<div class=\"p-5 bg-red-50/50 border border-red-200 rounded-xl space-y-2\"><span class=\"inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase bg-red-600 text-white\">Nasional</span>\r\n<h3 class=\"font-bold text-gray-900 text-sm\">SP4N - LAPOR!</h3>\r\n<p class=\"text-gray-600 leading-relaxed\">Layanan Aspirasi dan Pengaduan Online Rakyat yang terhubung langsung ke Kantor Staf Presiden &amp; Ombudsman.</p>\r\n<a href=\"https://www.lapor.go.id\" target=\"_blank\" class=\"inline-block text-xs font-bold text-red-600 hover:underline\" rel=\"noopener\">Kunjungi lapor.go.id &rarr;</a></div>\r\n<!-- Whistleblowing System -->\r\n<div class=\"p-5 bg-gray-50 border border-gray-200 rounded-xl space-y-2\"><span class=\"inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase bg-gray-900 text-white\">Internal Kemenimipas</span>\r\n<h3 class=\"font-bold text-gray-900 text-sm\">WBS (Whistleblowing System)</h3>\r\n<p class=\"text-gray-600 leading-relaxed\">Saluran pengaduan pelanggaran disiplin dan tindak pidana korupsi pegawai yang terhubung ke Inspektorat Jenderal.</p>\r\n<span class=\"inline-block text-xs font-semibold text-gray-700\">Kerahasiaan Identitas Dijamin 100%</span></div>\r\n</div>\r\n<!-- Pengaduan Langsung Rutan Pandeglang -->\r\n<div class=\"p-5 bg-white border border-gray-200 rounded-xl space-y-3\">\r\n<h3 class=\"font-bold text-gray-900 text-sm\">Pengaduan Langsung Unit Rutan Pandeglang</h3>\r\n<div class=\"grid grid-cols-1 sm:grid-cols-2 gap-3 text-gray-600\">\r\n<div class=\"p-3 bg-gray-50 rounded-lg\"><span class=\"font-bold text-gray-900 block\">WhatsApp Pengaduan / Dumas:</span> <span class=\"text-sm font-semibold text-red-600\">0812-XXXX-XXXX</span></div>\r\n<div class=\"p-3 bg-gray-50 rounded-lg\"><span class=\"font-bold text-gray-900 block\">Email Pengaduan:</span> <span class=\"text-sm font-semibold text-gray-900\">pengaduan@rutanpandeglang.go.id</span></div>\r\n</div>\r\n<p class=\"text-gray-500 pt-1\">Atau masukkan surat pengaduan fisik ke dalam <strong>Kotak Pengaduan</strong> yang tersedia di ruang tunggu pendaftaran kunjungan rutan.</p>\r\n</div>\r\n</div>\r\n</div>',10,0,'publikasi','2026-10-15 02:41:43','2026-10-15 04:27:20'),(19,'informasi-publik','lakip','LAKIP','Laporan pertanggungjawaban pencapaian target sasaran strategis dan anggaran tahunan.','dokumen',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\r\n<div class=\"space-y-4 text-xs\">\r\n<p class=\"text-sm leading-relaxed\">LAKIP merupakan wujud akuntabilitas pelaksanaan tugas dan fungsi yang dipercayakan kepada Rumah Tahanan Negara Kelas IIB Pandeglang atas penggunaan anggaran negara secara transparan dan berorientasi pada hasil (*outcome*).</p>\r\n<!-- Tabel Unduh Dokumen LAKIP -->\r\n<div class=\"overflow-x-auto border border-gray-200 rounded-xl shadow-xs\">\r\n<table class=\"w-full text-left\">\r\n<thead class=\"bg-gray-100 text-gray-800 uppercase text-[10px] tracking-wider\">\r\n<tr>\r\n<th class=\"py-3 px-4\">Nama Dokumen</th>\r\n<th class=\"py-3 px-4\">Tahun Anggaran</th>\r\n<th class=\"py-3 px-4 text-center\">Status</th>\r\n<th class=\"py-3 px-4 text-center\">Aksi Unduh</th>\r\n</tr>\r\n</thead>\r\n<tbody class=\"divide-y divide-gray-200\">\r\n<tr>\r\n<td class=\"py-3 px-4 font-semibold text-gray-900\">LAKIP Rutan Kelas IIB Pandeglang Tahun 2025</td>\r\n<td class=\"py-3 px-4 text-gray-500\">TA 2025</td>\r\n<td class=\"py-3 px-4 text-center\"><span class=\"px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-700\">Terverifikasi</span></td>\r\n<td class=\"py-3 px-4 text-center\"><span class=\"inline-flex items-center gap-1 text-red-600 font-bold hover:underline cursor-pointer\"> <svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z\"></path></svg> Unduh PDF </span></td>\r\n</tr>\r\n<tr>\r\n<td class=\"py-3 px-4 font-semibold text-gray-900\">LAKIP Rutan Kelas IIB Pandeglang Tahun 2024</td>\r\n<td class=\"py-3 px-4 text-gray-500\">TA 2024</td>\r\n<td class=\"py-3 px-4 text-center\"><span class=\"px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-700\">Terverifikasi</span></td>\r\n<td class=\"py-3 px-4 text-center\"><span class=\"inline-flex items-center gap-1 text-red-600 font-bold hover:underline cursor-pointer\"> <svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z\"></path></svg> Unduh PDF </span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n</div>\r\n</div>',1,0,'publikasi','2026-10-15 02:41:43','2026-10-15 04:23:10'),(20,'informasi-publik','dipa','DIPA','Transparansi alokasi pagu anggaran belanja dan program kerja tahun berjalan.','dokumen',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\r\n<div class=\"space-y-4 text-xs\">\r\n<p class=\"text-sm leading-relaxed\">Sebagai bentuk komitmen keterbukaan informasi publik dan akuntabilitas keuangan negara, berikut disajikan ringkasan Daftar Isian Pelaksanaan Anggaran (DIPA) Rumah Tahanan Negara Kelas IIB Pandeglang.</p>\r\n<!-- Tabel Ringkasan Pagu Anggaran -->\r\n<div class=\"overflow-x-auto border border-gray-200 rounded-xl shadow-xs\">\r\n<table class=\"w-full text-left\">\r\n<thead class=\"bg-gray-100 text-gray-800 uppercase text-[10px] tracking-wider\">\r\n<tr>\r\n<th class=\"py-3 px-4\">Tahun Anggaran</th>\r\n<th class=\"py-3 px-4\">Nomor SP DIPA</th>\r\n<th class=\"py-3 px-4\">Program Utama</th>\r\n<th class=\"py-3 px-4 text-center\">Dokumen</th>\r\n</tr>\r\n</thead>\r\n<tbody class=\"divide-y divide-gray-200\">\r\n<tr>\r\n<td class=\"py-3 px-4 font-bold text-gray-900\">TA 2026</td>\r\n<td class=\"py-3 px-4 font-mono text-gray-600\">SP DIPA-013.05.2.XXXXXX/2026</td>\r\n<td class=\"py-3 px-4 text-gray-700\">Program Penegakan dan Pelayanan Hukum / Pemasyarakatan</td>\r\n<td class=\"py-3 px-4 text-center\"><span class=\"text-red-600 font-bold hover:underline cursor-pointer\">Lihat Salinan</span></td>\r\n</tr>\r\n<tr>\r\n<td class=\"py-3 px-4 font-bold text-gray-900\">TA 2025</td>\r\n<td class=\"py-3 px-4 font-mono text-gray-600\">SP DIPA-013.05.2.XXXXXX/2025</td>\r\n<td class=\"py-3 px-4 text-gray-700\">Program Penegakan dan Pelayanan Hukum / Pemasyarakatan</td>\r\n<td class=\"py-3 px-4 text-center\"><span class=\"text-red-600 font-bold hover:underline cursor-pointer\">Lihat Salinan</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n<div class=\"p-4 bg-gray-50 border border-gray-200 rounded-xl space-y-1\"><span class=\"font-bold text-gray-900\">Komponen Utama Anggaran DIPA:</span>\r\n<ul class=\"list-disc list-inside text-gray-600 space-y-0.5\">\r\n<li>Belanja Pegawai (Gaji pokok dan tunjangan kinerja ASN)</li>\r\n<li>Belanja Barang Operasional (Bahan makanan WBP, pemeliharaan gedung &amp; kendaraan dinas, listrik, air)</li>\r\n<li>Belanja Modal (Pengadaan sarana pengamanan dan inventaris perkantoran)</li>\r\n</ul>\r\n</div>\r\n</div>\r\n</div>',2,0,'publikasi','2026-10-15 02:41:43','2026-10-15 04:23:22'),(21,'informasi-publik','laporan-tahunan','Laporan Tahunan','Rekapitulasi capaian kinerja, pelayanan, dan kegiatan operasional setiap tahun.','buku',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\n    <div class=\"space-y-4 text-xs\">\n        <p class=\"text-sm leading-relaxed\">\n            Laporan Tahunan merupakan dokumen komprehensif yang menyajikan pencapaian program kerja, data pelayanan tahanan, statistik hunian, serta pelaksanaan kegiatan pembinaan dan pengamanan selama satu tahun anggaran di Rumah Tahanan Negara Kelas IIB Pandeglang.\n        </p>\n\n        <!-- Tabel Unduh Dokumen Laporan Tahunan -->\n        <div class=\"overflow-x-auto border border-gray-200 rounded-xl shadow-xs\">\n            <table class=\"w-full text-left\">\n                <thead class=\"bg-gray-100 text-gray-800 uppercase text-[10px] tracking-wider\">\n                    <tr>\n                        <th class=\"py-3 px-4\">Nama Dokumen</th>\n                        <th class=\"py-3 px-4\">Tahun Anggaran</th>\n                        <th class=\"py-3 px-4 text-center\">Status</th>\n                        <th class=\"py-3 px-4 text-center\">Aksi Unduh</th>\n                    </tr>\n                </thead>\n                <tbody class=\"divide-y divide-gray-200\">\n                    <tr>\n                        <td class=\"py-3 px-4 font-semibold text-gray-900\">Laporan Tahunan Rutan Kelas IIB Pandeglang Tahun 2025</td>\n                        <td class=\"py-3 px-4 text-gray-500\">TA 2025</td>\n                        <td class=\"py-3 px-4 text-center\"><span class=\"px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-700\">Terverifikasi</span></td>\n                        <td class=\"py-3 px-4 text-center\">\n                            <span class=\"inline-flex items-center gap-1 text-red-600 font-bold hover:underline cursor-pointer\">\n                                <svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z\"/></svg>\n                                Unduh PDF\n                            </span>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td class=\"py-3 px-4 font-semibold text-gray-900\">Laporan Tahunan Rutan Kelas IIB Pandeglang Tahun 2024</td>\n                        <td class=\"py-3 px-4 text-gray-500\">TA 2024</td>\n                        <td class=\"py-3 px-4 text-center\"><span class=\"px-2 py-0.5 rounded text-[10px] font-bold bg-emerald-100 text-emerald-700\">Terverifikasi</span></td>\n                        <td class=\"py-3 px-4 text-center\">\n                            <span class=\"inline-flex items-center gap-1 text-red-600 font-bold hover:underline cursor-pointer\">\n                                <svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z\"/></svg>\n                                Unduh PDF\n                            </span>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <div class=\"p-4 bg-gray-50 border border-gray-200 rounded-xl space-y-1\">\n            <span class=\"font-bold text-gray-900\">Cakupan Laporan Tahunan:</span>\n            <ul class=\"list-disc list-inside text-gray-600 space-y-0.5\">\n                <li>Pelayanan tahanan dan data hunian (kapasitas vs. isi)</li>\n                <li>Program pembinaan kepribadian dan kemandirian WBP</li>\n                <li>Capaian keamanan, ketertiban, dan penegakan disiplin</li>\n                <li>Realisasi anggaran dan program kerja instansi</li>\n            </ul>\n        </div>\n    </div>\n</div>\n',3,0,'publikasi','2026-10-15 02:41:43','2026-10-15 02:41:43'),(22,'informasi-publik','laporan-keuangan','Laporan Keuangan','Realisasi anggaran dan pertanggungjawaban keuangan negara.','grafik',NULL,'<div class=\"space-y-6 text-gray-700 leading-relaxed text-sm\">\r\n<div class=\"space-y-4 text-xs\">\r\n<p class=\"text-sm leading-relaxed\">Sebagai bentuk akuntabilitas pengelolaan keuangan negara, Rumah Tahanan Negara Kelas IIB Pandeglang mempublikasikan laporan keuangan yang mencakup neraca, laporan realisasi anggaran (LRA), laporan operasional (LO), dan catatan atas laporan keuangan (CaLK) sesuai Standar Akuntansi Pemerintahan (SAP).</p>\r\n<!-- Tabel Unduh Dokumen Laporan Keuangan -->\r\n<div class=\"overflow-x-auto border border-gray-200 rounded-xl shadow-xs\">\r\n<table class=\"w-full text-left\">\r\n<thead class=\"bg-gray-100 text-gray-800 uppercase text-[10px] tracking-wider\">\r\n<tr>\r\n<th class=\"py-3 px-4\">Nama Dokumen</th>\r\n<th class=\"py-3 px-4\">Periode</th>\r\n<th class=\"py-3 px-4 text-center\">Status Audit</th>\r\n<th class=\"py-3 px-4 text-center\">Aksi Unduh</th>\r\n</tr>\r\n</thead>\r\n<tbody class=\"divide-y divide-gray-200\">\r\n<tr>\r\n<td class=\"py-3 px-4 font-semibold text-gray-900\">Laporan Keuangan Semester II TA 2025</td>\r\n<td class=\"py-3 px-4 text-gray-500\">Juli &ndash; Desember 2025</td>\r\n<td class=\"py-3 